function running(p){return p.tasks.filter(t=>t.status==='doing'&&t.agent)}
function workerName(id){return agents.find(a=>a.id===id)?.name||'未分派'}
function workerNames(p){return [...new Set(running(p).map(t=>workerName(t.agent)))].join('、')}
function updateDerived(){ensureHierarchy();for(const p of projects){if(['↗','◈','▤','▥','◇'].includes(p.icon)||!/\p{Extended_Pictographic}/u.test(p.icon||''))p.icon=randomProjectEmoji();p.version??=1;p.tasks.forEach((t,i)=>{t.id??=`${p.id}-${i}`;t.phase??=t.status==='doing'?'working':t.status;t.readVersion??=t.status==='doing'?p.version:0});p.status=p.tasks.some(t=>t.status==='error')?'error':running(p).length?'doing':p.tasks.length&&p.tasks.every(t=>t.status==='done')?'done':'todo'}for(const a of agents){const jobs=projects.flatMap(p=>running(p).filter(t=>t.agent===a.id).map(t=>({p,t})));const errors=projects.flatMap(p=>p.tasks.filter(t=>t.agent===a.id&&t.status==='error'));a.hasError=errors.length>0;a.active=jobs.length>0;a.status=jobs.length?jobs.map(({p,t})=>`${t.phase==='reading'?'正在阅读 README':'正在执行'} · ${p.name} / ${t.name}`).join('；')+(errors.length?`；${errors.length} 项异常待处理`:''):errors.length?`异常待处理 · ${errors.map(t=>t.name).join('、')}`:'等待新任务'}}
function runBadge(p){return `${p.paused?'<span class="badge todo">已暂停 · 全员停手</span>':''}${p.status!=='doing'?`<span class="badge ${p.status}">${labels[p.status]}</span>`:''}${running(p).length?`<span class="run-state"><i class="run-dot"></i>${esc(workerNames(p))} 正在跑</span>`:''}`}
function sync(){updateDerived();saveState();$('#project-nav').innerHTML=projects.filter(p=>running(p).length).map(p=>`<button class="nav ${current===p.id?'active':''}" onclick="project(${p.id})"><span class="ic">${p.icon}</span><span>${esc(p.name)}<small class="run-state"><i class="run-dot"></i>${esc(workerNames(p))} 正在跑</small></span></button>`).join('');$('#home-nav').classList.toggle('active',view==='home');$('#agent-count').textContent=agents.length+managers.length+1;$('#team-list').innerHTML=hierarchyTeam();renderBreadcrumbs()}
function rows(list){return list.length?list.map(p=>{const done=p.tasks.filter(t=>t.status==='done').length,pc=p.tasks.length?Math.round(done/p.tasks.length*100):0;return `<div class="project ${p.status==='doing'?'running-project':''}"><button class="project-link" onclick="project(${p.id})"><span class="picon">${p.icon}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.desc)}</small>${runBadge(p)}</span></button><div class="progress"><span class="small muted">${done}/${p.tasks.length} 任务</span><div class="bar"><i style="width:${pc}%"></i></div></div>${projectControls(p)}<span aria-hidden="true"></span></div>`}).join(''):'<div class="empty">这里还没有项目，点击右上角开启新项目。</div>'}
function project(id){updateDerived();const p=projects.find(p=>p.id===id);if(!p)return home();if(view!=='project')projectTrail=navigationPath();view='project';current=id;$('#crumb').textContent=p.name;$('#content').innerHTML=`<button class="back" onclick="home()">返回项目总览</button><div class="heading"><div><h1>${esc(p.name)}</h1><p>${esc(p.desc)}</p><div style="margin-top:12px">${runBadge(p)}</div></div><div class="project-control-group">${projectControls(p)}<details class="project-menu"><summary aria-label="项目更多操作" title="更多操作"><svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><circle cx="9" cy="4" r="1.2"/><circle cx="9" cy="9" r="1.2"/><circle cx="9" cy="14" r="1.2"/></svg></summary><div class="project-menu-popover"><button onclick="openProjectDelete(${id})">删除项目</button></div></details></div></div><div class="small muted" style="margin-bottom:16px">项目状态由员工执行反馈自动汇总 · 当前为模拟运行</div>${stats(p.tasks,true)}<div class="panel"><div class="panel-head"><h2>▤ README <span class="muted small">v${p.version}</span></h2><button class="secondary icon-button" aria-label="编辑 README" title="编辑 README" onclick="editReadme(${id})">${uiIcon("edit")}</button></div><div class="readme">${esc(p.readme)}</div><div class="readme-policy">每次启动 / 继续执行前均须阅读；更新后，执行中的员工先重读最新版本再继续。</div></div><div class="section-title"><h2>任务看板</h2><button class="secondary" onclick="document.getElementById('work-history').scrollIntoView({behavior:'smooth'})">工作日志</button><button class="primary" onclick="assign(${id})">✧ 指挥分派</button></div><div class="task-grid">${stateOrder.map(s=>`<div class="task-column status-${s}" id="col-${s}"><h3>${labels[s]} · ${p.tasks.filter(t=>t.status===s).length}</h3>${p.tasks.filter(t=>t.status===s).map(t=>{const i=p.tasks.indexOf(t);return `<div class="task status-${s} ${s==='doing'?'running-task':''}"><span class="task-state">${labels[s]}</span><div class="task-title">${esc(t.name)}<button class="delete-btn" aria-label="删除任务 ${esc(t.name)}" title="删除任务" onclick="deleteTask(${id},${i})">${uiIcon("trash")}</button></div><small class="${s==='doing'?'run-state':''}">${s==='doing'?'<i class="run-dot"></i>':''}${t.agent?esc(workerName(t.agent)):t.formerAgentName?esc(t.formerAgentName)+'（历史执行）':'未分派员工'}${t.supervisorId?'（'+esc(findAgent(t.supervisorId)?.name||'性能指挥')+'直属）':''} · ${t.phase==='reading'?`正在阅读 README v${p.version}`:s==='doing'?'正在执行':s==='error'?'异常，等待处理':s==='done'?'完成':t.phase==='paused'?'已暂停':'等待执行'}</small><small>${t.phase==='reading'?'阅读完成后自动继续':t.readVersion?`已读 README v${t.readVersion}${t.readmeReadAt?' · '+esc(t.readmeReadAt):''}${t.readVersion<p.version?' · 下次执行需重读':''}`:'启动时先阅读 README'}</small>${s==='error'?`<div class="error-reason">${esc(t.errorReason||'执行异常，请检查后重试')}</div>`:''}<div class="task-actions">${s==='doing'?`<button onclick="employeeFeedback(${id},${i},'paused')">模拟员工暂停</button><button onclick="reportError(${id},${i})">模拟员工报错</button>${t.phase==='working'?`<button onclick="submitJob(${id},${i})">提交作业</button>`:''}`:t.agent?`<button onclick="startTask(${id},${i})">${s==='error'?'重试任务':s==='done'?'重新执行':'启动执行'}</button>`:`<button onclick="assign(${id})">分派员工</button>`}</div></div>`}).join('')||'<div class="small muted">暂无任务</div>'}</div>`).join('')}</div><div class="commander"><h3 style="margin-bottom:12px">✧ 正在执行的 AI 员工</h3><p>${running(p).map(t=>`<span class="run-state"><i class="run-dot"></i>${esc(workerName(t.agent))}</span>：${esc(t.name)} · ${t.phase==='reading'?`正在重读 README v${p.version}`:`已读 v${t.readVersion}，执行中`}`).join('<br>')||'当前没有员工在执行任务；项目根据任务反馈显示异常、未开始或完成。'}</p></div>${historyPanel(id)}`;sync()}
function editReadme(id){const p=projects.find(p=>p.id===id);modal('编辑项目 README',`当前版本 v${p.version}。保存更改后，正在运行的员工将重新阅读。`,`<form onsubmit="event.preventDefault();saveReadme(this,${id})"><label class="field">README 内容<textarea name="readme" style="min-height:260px" required>${esc(p.readme)}</textarea></label><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="primary">保存并通知员工</button></div></form>`)}
function saveReadme(form,id){const p=projects.find(p=>p.id===id),value=new FormData(form).get('readme').trim();if(!value)return toast('README 不能为空');if(value===p.readme){closeModal();return toast('内容没有变化，版本保持不变')}p.readme=value;p.version++;const active=[...running(p)];logs.unshift([`「${p.name}」README 更新至 v${p.version}，${active.length} 项执行任务需要重读`,'刚刚']);for(const t of active)readBeforeRun(p,t);closeModal();refresh();toast(`README v${p.version} 已保存，执行员工正在同步`)}
function readBeforeRun(p,t){if(!t.agent||!supervisor(agents.find(a=>a.id===t.agent))||p.paused)return;const version=p.version,content=p.readme,token=(t.runToken||0)+1;t.runToken=token;t.status='doing';t.phase='reading';t.errorReason='';t.readVersion=0;logs.unshift([`${workerName(t.agent)} 开始阅读「${p.name}」README v${version}（模拟）`,'刚刚']);setTimeout(()=>{if(p.paused||!projects.includes(p)||!p.tasks.includes(t)||t.runToken!==token||t.status!=='doing'||p.version!==version)return;t.readVersion=version;t.readContext=content;t.readmeSnapshot=content;t.readmeReadAt=new Date().toLocaleString('zh-CN');t.phase='working';logs.unshift([`${workerName(t.agent)} 已读 README v${version}，开始「${t.name}」（模拟）`,'刚刚']);refresh()},1600)}
function startTask(id,i){const p=projects.find(p=>p.id===id),t=p?.tasks[i];if(p?.paused)return toast('项目已暂停，请先点击项目的开始按钮');if(!t?.agent)return toast('请先分派执行员工');readBeforeRun(p,t);refresh();toast('员工先阅读最新 README，再执行任务')}
function deleteProject(id){const p=projects.find(p=>p.id===id);if(!p)return;modal('删除项目',`删除「${esc(p.name)}」及其中 ${p.tasks.length} 个任务。相关模拟执行将停止，员工会保留。`,`<div class="modal-footer"><button class="secondary" onclick="closeModal()">取消</button><button class="danger" onclick="confirmDeleteProject(${id})">确认删除项目</button></div>`)}
function confirmDeleteProject(id){const p=projects.find(p=>p.id===id);if(!p)return;projects=projects.filter(x=>x.id!==id);logs.unshift([`项目「${p.name}」已删除，相关执行已停止`,'刚刚']);closeModal();refresh();toast('项目和任务已删除，员工已释放')}
function deleteTask(id,i){const p=projects.find(p=>p.id===id),t=p?.tasks[i];if(!t)return;modal('删除任务',`删除「${esc(t.name)}」。${t.status==='doing'?'该任务的模拟执行将立即停止。':''}`,`<div class="modal-footer"><button class="secondary" onclick="closeModal()">取消</button><button class="danger" onclick="confirmDeleteTask(${id},${i})">确认删除任务</button></div>`)}
function confirmDeleteTask(id,i){const p=projects.find(p=>p.id===id),t=p?.tasks[i];if(!t)return;p.tasks.splice(i,1);logs.unshift([`「${p.name}」已删除任务「${t.name}」`,'刚刚']);closeModal();refresh();toast('任务已删除，项目状态已重新汇总')}

const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={doing:'进行中',error:'异常',todo:'未开始',done:'完成'},en={doing:'Doing',error:'Error',todo:'To Do',done:'Done'},stateOrder=['doing','error','todo','done'];
let commander={id:0,name:'总指挥',role:'团队管理与任务调度',dept:'指挥中心',status:'统筹全部员工',color:'',model:'commander-model',endpoint:'https://api.example.com/v1'};
let managerView=null;
let managers=['策略','研究','内容','数据'].map((name,i)=>({id:-(i+1),name:name+'指挥',dept:name+'部',role:'性能指挥',level:2,parentId:0,status:'等待调度',model:'manager-model',endpoint:'https://api.example.com/v1'}));
let agents=[{id:1,name:'小策',role:'策略规划师',dept:'策略部',status:'分析求职目标',color:'',model:'strategy-model',endpoint:'https://api.example.com/v1'},{id:2,name:'小研',role:'研究分析师',dept:'研究部',status:'整理行业报告',color:'mint',model:'research-model',endpoint:'https://api.example.com/v1'},{id:3,name:'小文',role:'内容创作师',dept:'内容部',status:'优化简历内容',color:'peach',model:'writing-model',endpoint:'https://api.example.com/v1'},{id:4,name:'小数',role:'数据分析师',dept:'数据部',status:'等待新任务',color:'lilac',model:'analysis-model',endpoint:'https://api.example.com/v1'}];
let projects=[{id:1,name:'开启下一段职业旅程',desc:'求职项目 · 从方向定位到拿到心仪 Offer',status:'doing',icon:'↗',readme:'项目目标\n找到匹配个人优势的 AI 产品经理岗位，并完成高质量投递。\n\n执行范围\n1. 明确目标岗位与能力画像\n2. 优化简历与项目作品集\n3. 筛选目标公司，准备面试\n\n交付标准\n完成一份定制简历、10 家目标公司清单及一套面试问答。',tasks:[{name:'梳理个人优势与求职方向',status:'done',agent:1},{name:'收集目标岗位与公司信息',status:'done',agent:2},{name:'优化简历与项目经历',status:'doing',agent:3},{name:'分析目标岗位匹配度',status:'doing',agent:1},{name:'准备模拟面试题库',status:'todo',agent:null},{name:'制定每周投递计划',status:'todo',agent:null}]},{id:2,name:'AI 行业趋势研究',desc:'研究项目 · 追踪产品与市场的新变化',status:'doing',icon:'◈',readme:'项目目标\n整理 AI 行业的产品动态、市场机会和竞争格局。\n\n交付标准\n形成一份结构化研究报告与可行动的机会清单。',tasks:[{name:'确定研究范围',status:'done',agent:1},{name:'整理行业报告',status:'doing',agent:2},{name:'汇总市场数据',status:'todo',agent:null}]},{id:3,name:'个人知识库搭建',desc:'知识管理 · 让积累成为可复用的资产',status:'todo',icon:'▤',readme:'项目目标\n建立可检索、可维护的个人知识库。\n\n交付标准\n完成资料分类规范和首批资料归档。',tasks:[{name:'设计知识分类',status:'todo',agent:null},{name:'导入历史笔记',status:'todo',agent:null}]},{id:4,name:'十月个人财务复盘',desc:'财务项目 · 理清收支，优化预算',status:'done',icon:'▥',readme:'项目目标\n总结十月收支并制定下月预算。\n\n项目结果\n已完成收支分类与预算建议。',tasks:[{name:'整理收支明细',status:'done',agent:4},{name:'输出预算建议',status:'done',agent:4}]}];
let view='home',filter='all',current=null,logs=[['小文正在优化「开启下一段职业旅程」的简历内容','刚刚'],['总指挥将「整理行业报告」分派给小研','12 分钟前'],['小数完成了「十月个人财务复盘」','35 分钟前']],chats={},modalReturn=null;

const STORAGE_KEY='linghang-command-center-v2';
function saveState(){if(typeof accountStage==='function')accountStage()}
function loadState(){try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(Array.isArray(x?.agents)&&Array.isArray(x?.projects)){if(x.commander)Object.assign(commander,{model:x.commander.model||commander.model,endpoint:x.commander.endpoint||commander.endpoint});if(Array.isArray(x.managers)&&x.managers.length)managers=x.managers;agents=x.agents;projects=x.projects;logs=Array.isArray(x.logs)?x.logs:logs}}catch(e){}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3000)}
function stats(items,isTask=false){return `<div class="stats four-states">${stateOrder.map(s=>`<button class="stat status-${s} ${!isTask&&filter===s?'selected':''}" onclick="${isTask?`document.getElementById('col-${s}').scrollIntoView({behavior:'smooth',block:'center'})`:`home('${s}')`}"><div class="small"><span class="sicon">${({doing:'◷',error:'!',todo:'○',done:'✓'})[s]}</span>${labels[s]}</div><div class="num">${String(items.filter(p=>p.status===s).length).padStart(2,'0')}</div><small>${isTask?'项任务':'个项目'}${({doing:'正在执行',error:'需要处理',todo:'等待执行',done:'已完成'})[s]}</small></button>`).join('')}</div>`}
function home(f='all'){updateDerived();view='home';current=null;filter=f;$('#crumb').textContent='总指挥';$('#content').innerHTML=`<div class="heading"><div><h1>把目标交给团队，把时间留给你。</h1><p>掌握全局进展，让每一个想法有序向前。</p></div><span class="live"><span class="dot"></span>工作台运行中</span></div>${stats(projects)}<section class="panel"><div class="panel-head"><h2>项目总览 <span class="muted small">${projects.length}</span></h2><div class="tabs">${['all',...stateOrder].map(s=>`<button class="tab ${filter===s?'on':''}" onclick="home('${s}')">${s==='all'?'全部':labels[s]}</button>`).join('')}</div></div>${rows(projects.filter(p=>filter==='all'||p.status===filter))}</section><section class="panel"><div class="panel-head"><h2>团队动态</h2><span class="small muted">最新协作进展</span></div><div class="timeline">${teamEvents(logs.slice(0,5),true)}</div><div class="activity-footer"><span class="small muted">最近 ${Math.min(logs.length,5)} 条动态</span><button class="secondary" onclick="showTeamActivity()">查看详情</button></div></section><div class="footer-hint">领航 AI · 让协作井然有序</div>`;sync()}
function modal(title,desc,body){modalReturn=document.activeElement;$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close" aria-label="关闭" onclick="closeModal()">×</button></div><p>${desc}</p>${body}`;$('#overlay').classList.add('open');setTimeout(()=>$('#modal input, #modal select, #modal button')?.focus(),30)}
function closeModal(){$('#overlay').classList.remove('open');modalReturn?.focus()}
function newProject(prefill=''){modal('开启一个新项目','01 创建项目 → 02 创建员工 Agent',`<form onsubmit="event.preventDefault();createProject(this)"><label class="field">项目名称<input name="name" required maxlength="40" placeholder="例如：开启下一段职业旅程" value="${esc(prefill)}"></label><label class="field">项目目标 / README<textarea name="goal" required placeholder="希望团队帮助你完成什么？"></textarea></label><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="primary">创建项目，下一步</button></div></form>`)}
function createProject(form){const d=new FormData(form),id=Date.now();projects.push({id,name:d.get('name').trim()||'新项目',desc:'自定义项目 · 等待团队启动',status:'todo',icon:randomProjectEmoji(),readme:d.get('goal'),tasks:[]});project(id);newAgent(id)}
function command(form){const value=form.querySelector('input').value;newProject(value)}
function settings(){view='settings';current=null;$('#crumb').textContent='Agent API 配置';$('#content').innerHTML=`<div class="heading"><div><h1>三级 Agent，独立配置。</h1><p>分别设置模型、API 端点与密钥占位，适配不同工作职责。</p></div></div><div class="notice" style="margin:0 0 22px">演示模式：以下均为模拟模型与示例端点。密钥栏仅显示占位符，不接收、不存储真实密钥，也不会发起 API 请求。</div><div class="panel">${[commander,...managers,...agents].map(a=>`<div class="config-row"><div><h3>${esc(a.name)} · ${esc(a.role)}</h3><p>${esc(a.model)} · ${a.id===0?'L1 总指挥':managers.some(m=>m.id===a.id)?'L'+managerLevel(a)+' '+esc(a.role):'L3 员工'} · ${esc(a.dept)}</p><p style="font-size:10px">${esc(a.endpoint)}</p></div><button class="secondary" onclick="configure(${a.id})">配置</button></div>`).join('')}</div>`;sync()}
function configure(id){const a=findAgent(id);modal(`${esc(a.name)} · API 配置`,'每个 Agent 的设置独立生效，仅用于本次原型演示。',`<form onsubmit="event.preventDefault();saveConfig(this,${id})"><label class="field">API 模型名称<input name="model" value="${esc(a.model)}" required></label><label class="field">API 端点<input name="endpoint" type="url" value="${esc(a.endpoint)}" required></label><label class="field">API 密钥（仅占位）<input type="password" placeholder="••••••••••••••••" disabled aria-label="密钥占位，不可输入"></label><div class="notice">真实产品中应由服务端安全保存密钥。此处不收集密钥；保存仅更新演示中的模型名称和端点。</div><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="primary">保存配置</button></div></form>`)}
function saveConfig(form,id){const d=new FormData(form),endpoint=d.get('endpoint');if(!/^https?:\/\//i.test(endpoint)){toast('请输入 HTTP 或 HTTPS 端点');return}Object.assign(findAgent(id),{model:d.get('model'),endpoint});saveState();closeModal();settings();toast('已保存此 Agent 的演示配置')}
function chat(id){const a=findAgent(id);chats[id]??=[{who:'ai',text:`你好，我是${a.name}，负责${a.role}相关工作。当前状态：${a.status}。你可以在这里询问进度或沟通想法。`}];modal(`与${esc(a.name)}对话`,`${esc(a.dept)} · ${esc(a.role)} · 模拟回复`, `<div class="messages" id="messages"></div><form class="command-input" onsubmit="event.preventDefault();sendChat(this,${id})"><input required aria-label="聊天消息" placeholder="输入你的消息…"><button class="primary">发送</button></form>`);renderChat(id)}
function renderChat(id){$('#messages').innerHTML=chats[id].map(m=>`<div class="bubble ${m.who==='me'?'me':''}">${esc(m.text)}</div>`).join('');$('#messages').scrollTop=$('#messages').scrollHeight}
function sendChat(form,id){const a=findAgent(id),input=form.querySelector('input'),v=input.value.trim();if(!v)return;chats[id].push({who:'me',text:v},{who:'ai',text:id===0?commanderReply(v):`收到「${v}」。我当前${a.status}。这是演示回复；如果需要安排执行，请进入项目，使用「指挥分派」为我分配任务。`});input.value='';renderChat(id)}
document.addEventListener('keydown',e=>{if(!$('#overlay').classList.contains('open'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const a=[...$('#modal').querySelectorAll('button,input:not(:disabled),select,textarea')],first=a[0],last=a[a.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function reportError(id,i){const t=projects.find(p=>p.id===id)?.tasks[i];if(!t||t.status!=='doing')return;modal('模拟员工报告异常',`${esc(workerName(t.agent))} · ${esc(t.name)}`,`<form onsubmit="event.preventDefault();setTaskError(this,${id},${i})"><label class="field">异常原因<textarea name="reason" required placeholder="例如：接口超时，需要重试"></textarea></label><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="danger">确认报告异常</button></div></form>`)}
function setTaskError(form,id,i){const p=projects.find(p=>p.id===id),t=p?.tasks[i],reason=new FormData(form).get('reason').trim();if(!t||!reason)return;t.runToken=(t.runToken||0)+1;t.status='error';t.phase='error';t.errorReason=reason;logs.unshift([`${workerName(t.agent)} 报告「${t.name}」异常：${reason}（模拟）`,'刚刚']);closeModal();refresh();toast('任务已标记异常，可查看原因并重试')}

function openProjectDelete(id){const menu=$('.project-menu');if(menu){menu.open=false;menu.querySelector('summary').focus()}deleteProject(id)}
document.addEventListener('click',e=>{const menu=$('.project-menu[open]');if(menu&&!menu.contains(e.target))menu.open=false});
document.addEventListener('keydown',e=>{const menu=$('.project-menu[open]');if(e.key==='Escape'&&menu){menu.open=false;menu.querySelector('summary').focus()}});

function chooseProjectFor(id){if(!projects.length){toast('请先创建一个项目');return}modal(`为${esc(workerName(id))}分派任务`,'选择项目后，可以分派现有任务或创建新任务。',`<form onsubmit="event.preventDefault();assign(Number(new FormData(this).get('project')),${id})"><label class="field">选择项目<select name="project">${projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="primary">下一步</button></div></form>`)}
function commanderReply(v){updateDerived();return `收到「${v}」。我正在统筹 ${agents.length} 位员工、${projects.length} 个项目，其中 ${projects.flatMap(p=>running(p)).length} 项任务执行中、${projects.flatMap(p=>p.tasks).filter(t=>t.status==='error').length} 项异常。请在「管理员工」中选择分派、暂停或恢复；这是模拟指挥回复，不会调用真实模型。`}
function backupKey(id){return `linghang-project-backups-v1:${id}`}
function projectCopy(p){const c=JSON.parse(JSON.stringify(p));c.supervisors=managers.map(m=>({id:m.id,name:m.name,parentId:0,level:2}));c.assignees=agents.filter(a=>p.tasks.some(t=>t.agent===a.id)).map(a=>({id:a.id,name:a.name,role:a.role,dept:a.dept,parentId:a.parentId,level:3}));c.status=c.tasks.some(t=>t.status==='error')?'error':c.tasks.some(t=>t.status==='doing')?'doing':c.tasks.length&&c.tasks.every(t=>t.status==='done')?'done':'todo';return c}
function readHistory(id){return JSON.parse(JSON.stringify(accountHistories[id]||[]))}
function makeCommit(p,message,author,previous){return {id:crypto.randomUUID(),parent:previous?.id||null,version:(previous?.version||0)+1,time:new Date().toISOString(),author,message,snapshot:projectCopy(p)}}
function writeHistory(id,h){const old=accountHistories[id];accountHistories[id]=JSON.parse(JSON.stringify(h));try{accountDirty=true;accountCache();accountStage()}catch(e){if(old)accountHistories[id]=old;else delete accountHistories[id];throw e}}
function backupCommit(p,message,author,baseline){const h=readHistory(p.id);if(!h.length&&baseline)h.push(makeCommit(baseline,'初始基线（首次提交前）','系统',null));const c=makeCommit(p,message,author,h.at(-1));h.push(c);writeHistory(p.id,h);return c}
function backupFailure(){toast('备份未保存，操作未提交。请检查浏览器存储空间或权限。')}
function historyPanel(id){let h;try{h=readHistory(id)}catch(e){return '<div class="notice error-state">无法读取当前账号的备份，请下载本机副本并检查同步状态。</div>'}return `<section class="panel work-history" id="work-history"><div class="panel-head"><h2>工作日志 <span class="muted small">${h.length} 次版本记录</span></h2><div class="history-actions"><button class="secondary" onclick="manualCommit(${id})">＋ 提交当前版本</button><button class="secondary" onclick="exportHistory(${id})" ${h.length?'':'disabled'}>下载全部备份</button></div></div><div class="readme-policy">每次作业提交先备份，再标记完成。版本包含 README、全部任务及产出说明。版本备份随账号同步到云端；请确认左下角显示“已同步云端”。同步前请勿清理浏览器数据。</div>${h.length?h.slice().reverse().map((c,i)=>`<div class="commit-row"><span class="commit-node"></span><div class="commit-info"><div><strong>${esc(c.message)}</strong>${i===0?'<span class="badge doing" style="margin-left:8px">最新提交</span>':''}</div><p><code>${c.id.slice(0,8)}</code> · v${c.version} · ${esc(c.author)} · ${new Date(c.time).toLocaleString('zh-CN')}</p><small>README v${c.snapshot.version||1} · ${c.snapshot.tasks.length} 个任务 · ${c.snapshot.tasks.filter(t=>t.status==='done').length} 个完成 · <span class="backup-ok">版本已生成 · 同步状态见账号区</span></small></div><button class="secondary" onclick="viewCommit(${id},'${c.id}')">查看版本</button></div>`).join(''):'<div class="empty">还没有提交记录。员工提交作业后，会自动生成版本和备份。</div>'}</section>`}
function submitJob(id,i){const p=projects.find(p=>p.id===id),t=p?.tasks[i];if(!t||t.phase!=='working')return;modal('提交作业并备份',`${esc(workerName(t.agent))} · ${esc(t.name)}。备份成功后才会标记完成。`,`<form onsubmit="event.preventDefault();finishJob(this,${id},${i})"><label class="field">提交说明<input name="message" required maxlength="160" value="${esc('完成：'+t.name)}"></label><label class="field">作业产出 / 结果说明<textarea name="result" required placeholder="记录本次完成的内容、结论或产出链接"></textarea></label><div class="notice">生成当前项目的数据快照，并随账号同步到云端。本演示不包含外部链接指向的文件内容。</div><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="primary">提交并备份</button></div></form>`)}
function finishJob(form,id,i){const d=new FormData(form),message=d.get('message').trim(),result=d.get('result').trim();if(!message||!result)return toast('请填写提交说明和作业产出');if(employeeFeedback(id,i,'done',{message,result}))closeModal()}
function employeeFeedback(id,i,state,submission){const p=projects.find(p=>p.id===id),t=p?.tasks[i];if(p?.paused||!t||t.status!=='doing'||!['paused','done'].includes(state))return false;if(state==='done'&&(t.phase!=='working'||t.readVersion!==p.version)){toast('员工需要先读完最新 README');return false}if(state==='done'){const next=projectCopy(p);Object.assign(next.tasks[i],{phase:'done',status:'done',result:submission?.result||'员工反馈作业完成（模拟）',submittedAt:new Date().toISOString()});try{const c=backupCommit(next,submission?.message||`完成：${t.name}`,workerName(t.agent),p);Object.assign(t,next.tasks[i]);t.lastCommit=c.id;logs.unshift([`${workerName(t.agent)} 提交「${t.name}」 · ${c.id.slice(0,8)} · 版本已生成，等待云端同步`,'刚刚'])}catch(e){backupFailure();return false}}else{t.phase='paused';t.status='todo';logs.unshift([`${workerName(t.agent)} 暂停「${t.name}」（模拟）`,'刚刚'])}t.runToken=(t.runToken||0)+1;refresh();if(state==='done')toast('作业已提交，版本备份已生成，请确认云端同步状态');return true}
function manualCommit(id){modal('提交项目当前版本','保存当前 README、全部任务和已有作业产出。',`<form onsubmit="event.preventDefault();saveManualCommit(this,${id})"><label class="field">提交说明<input name="message" required maxlength="160" placeholder="例如：调整本周目标与执行计划"></label><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="primary">提交并备份</button></div></form>`)}
function saveManualCommit(form,id){const p=projects.find(p=>p.id===id),msg=new FormData(form).get('message').trim();if(!p||!msg)return;try{const c=backupCommit(p,msg,'我');logs.unshift([`「${p.name}」提交版本 ${c.id.slice(0,8)}，版本已生成，等待云端同步`,'刚刚']);closeModal();refresh();toast('当前版本已备份')}catch(e){backupFailure()}}
function changeSummary(prev,next){if(!prev)return '初始版本';const changes=[];if(prev.readme!==next.readme)changes.push('README 已修改');const a=new Map(prev.tasks.map(t=>[t.id||t.name,t])),b=new Map(next.tasks.map(t=>[t.id||t.name,t]));for(const [key,t]of b){if(!a.has(key))changes.push(`新增任务：${t.name}`);else if(JSON.stringify(a.get(key))!==JSON.stringify(t))changes.push(`更新任务：${t.name}（${labels[t.status]}）`)}for(const [key,t]of a)if(!b.has(key))changes.push(`删除任务：${t.name}`);return changes.join('\n')||'任务与 README 无变化，记录当前版本'}
function viewCommit(id,cid){let h;try{h=readHistory(id)}catch(e){return backupFailure()}const i=h.findIndex(c=>c.id===cid),c=h[i];if(!c)return;modal(`项目版本 v${c.version}`,`${esc(c.author)} · ${c.id.slice(0,8)} · ${new Date(c.time).toLocaleString('zh-CN')}`,`<div class="commit-detail"><h3>${esc(c.message)}</h3><p class="small muted">父提交：${c.parent?c.parent.slice(0,8):'无（初始版本）'}</p><h3>相对上一版的变化</h3><pre>${esc(changeSummary(h[i-1]?.snapshot,c.snapshot))}</pre><h3>README 快照</h3><pre>${esc(c.snapshot.readme)}</pre><h3>任务快照与产出</h3>${c.snapshot.tasks.map(t=>`<div class="snapshot-task"><b>${esc(t.name)}</b><p>${labels[t.status]} · ${esc(workerName(t.agent))}</p>${t.result?`<pre>${esc(t.result)}</pre>`:''}</div>`).join('')}</div><div class="modal-footer"><button class="secondary" onclick="exportHistory(${id},'${cid}')">下载此版本</button><button class="primary" onclick="restorePrompt(${id},'${cid}')">恢复此版本</button></div>`)}
function restorePrompt(id,cid){modal('恢复历史版本','恢复前会自动备份当前数据，再生成一条恢复提交。历史记录不会删除；运行中的任务将暂停，恢复执行时重新阅读 README。',`<div class="modal-footer"><button class="secondary" onclick="closeModal()">取消</button><button class="primary" onclick="restoreCommit(${id},'${cid}')">备份当前并恢复</button></div>`)}
function restoreCommit(id,cid){const index=projects.findIndex(p=>p.id===id),currentProject=projects[index];if(!currentProject)return;try{const h=readHistory(id),target=h.find(c=>c.id===cid);if(!target)return;const restored=projectCopy(target.snapshot);restored.id=id;restored.version=Math.max(currentProject.version||1,restored.version||1)+1;for(const t of restored.tasks){t.runToken=(t.runToken||0)+1;if(t.status==='doing'){t.status='todo';t.phase='paused'}t.readVersion=0}h.push(makeCommit(currentProject,'恢复前自动备份','系统',h.at(-1)));h.push(makeCommit(restored,`恢复至 v${target.version}（${target.id.slice(0,8)}）`,'我',h.at(-1)));writeHistory(id,h);projects[index]=restored;logs.unshift([`「${restored.name}」恢复至历史版本 v${target.version}，已保留恢复前备份`,'刚刚']);closeModal();refresh();toast('历史版本已恢复，运行任务已暂停')}catch(e){backupFailure()}}
function exportHistory(id,cid){try{const h=readHistory(id),records=cid?h.filter(c=>c.id===cid):h;if(!records.length)return toast('暂无可下载的备份');const data={format:'linghang-project-backup',schemaVersion:1,exportedAt:new Date().toISOString(),projectId:id,commits:records};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`project-${id}-${cid?cid.slice(0,8):'all-backups'}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已生成 JSON 备份下载')}catch(e){toast('读取或导出备份失败，请检查浏览器权限')}}

function randomProjectEmoji(){const icons=["🚀","🌱","🎯","🧩","📚","🎨","🛠️","💡","🌟","🧭","🍀","🐳","🦊","🌈","🏔️","🪴","🎸","🪐","🧪","🍋"];const n=new Uint32Array(1);crypto.getRandomValues(n);return icons[n[0]%icons.length]}
function findAgent(id){return id===0?commander:managers.find(a=>a.id===id)||agents.find(a=>a.id===id)}
function supervisor(a){return managers.find(m=>m.id===a?.parentId)}
function commanderCard(){return `<div class="chief-card"><div class="agent"><div class="avatar chief-avatar">✧</div><button class="agent-main" onclick="commanderPanel()"><h3>总指挥 <span class="chief-tag">L1 一级</span></h3><p>统筹 ${managers.length} 位部门负责人</p><div class="state">全局规划 · 分层调度</div></button><button class="chat-btn" aria-label="与总指挥聊天" onclick="chat(0)" title="打开对话">${uiIcon("chat")}</button></div><button class="secondary chief-manage" onclick="commanderPanel()">管理指挥团队</button></div>`}
function hierarchyTeam(){return commanderCard()+managers.map(m=>`<div class="manager-group"><div class="agent"><div class="avatar manager-avatar">◈</div><button class="agent-main" onclick="managerPanel(${m.id})"><h3>${esc(m.name)} <span class="chief-tag">L${managerLevel(m)}</span></h3><p>${esc(m.role)} · ${esc(m.dept)}</p><div class="state">${agents.filter(a=>a.parentId===m.id).length} 位直属员工</div></button><button class="chat-btn" aria-label="与${esc(m.name)}聊天" onclick="chat(${m.id})" title="打开对话">${uiIcon("chat")}</button></div><div class="subordinate-list">${agents.filter(a=>a.parentId===m.id).map(a=>`<div class="agent"><div class="avatar ${a.color}">${esc(a.name.slice(0,1))}</div><button class="agent-main" onclick="department(${m.id})"><h3>${esc(a.name)} <span class="chief-tag">L3 员工</span></h3><p>${esc(a.role)}</p><div class="state ${a.hasError?'error-state':a.active?'run-state':''}"><span class="${a.active?'run-dot':'dot'}"></span>${esc(a.status)}</div></button><button class="chat-btn" aria-label="与${esc(a.name)}聊天" onclick="chat(${a.id})" title="打开对话">${uiIcon("chat")}</button></div>`).join('')||'<p class="small muted">尚无直属员工</p>'}</div></div>`).join('')}
function commanderPanel(){updateDerived();view='commander';current=null;$('#crumb').textContent='一级 · 总指挥';$('#content').innerHTML=`<button class="back" onclick="home()">返回总览</button><div class="heading"><div><h1>一级 · 总指挥</h1><p>总指挥 → 部门负责人 → 执行员工</p></div><button class="primary" onclick="newManager()">＋ 创建部门负责人</button></div><div class="commander"><h3>分层管理，各司其职</h3><p style="margin-top:12px">总指挥管理 ${managers.length} 位部门负责人；负责人分别安排下属 ${agents.length} 位三级员工执行具体任务。所有层级都有独立模型配置。<br>当前为模拟调度，每次执行前仍须阅读 README，提交作业时自动备份。</p><div class="chief-actions"><button class="primary" onclick="autoAssignAll()">通过部门负责人自动分派</button><button class="secondary" onclick="controlWorkers(null,'pause')">暂停全部团队</button><button class="secondary" onclick="controlWorkers(null,'resume')">恢复全部团队</button><button class="secondary" onclick="chat(0)">与总指挥对话</button></div></div><section class="panel"><div class="panel-head"><h2>部门负责人</h2><span class="muted small">${managers.length} 位</span></div>${managers.map(m=>`<div class="worker-row"><div class="avatar manager-avatar">◈</div><div class="worker-info"><h3>${esc(m.name)} · ${esc(m.role)} <span class="chief-tag">L${managerLevel(m)}</span></h3><p>上级：总指挥 · ${esc(m.dept)}</p><small>${esc(m.status)}</small></div><div class="chief-actions"><button class="secondary" onclick="managerPanel(${m.id})">管理下属</button><button class="secondary" onclick="controlWorkers(null,'pause',${m.id})">暂停团队</button><button class="secondary" onclick="controlWorkers(null,'resume',${m.id})">恢复团队</button></div></div>`).join('')}</section>`;sync()}
function managerPanel(id){const m=managers.find(m=>m.id===id);if(!m)return;updateDerived();view='manager';managerView=id;current=null;$('#crumb').textContent=`总指挥 / ${m.name}`;const children=agents.filter(a=>a.parentId===id),tasks=projects.flatMap(p=>p.tasks);$('#content').innerHTML=`<button class="back" onclick="commanderPanel()">一级总指挥</button><div class="heading"><div><h1>${esc(m.name)}</h1><p>L${managerLevel(m)} ${esc(m.role)} · 上级：总指挥 · ${esc(m.dept)}</p></div><button class="primary" onclick="newAgent(null,${id})">＋ 添加三级员工</button></div><div class="commander"><h3>只管理自己的直属员工</h3><p style="margin-top:12px">${esc(m.status)}。接收总指挥调度后，由本团队的三级员工执行。暂停、恢复和自动分派仅影响本团队。</p><div class="chief-actions"><button class="primary" onclick="autoAssignAll(${id})">分派本团队任务</button><button class="secondary" onclick="controlWorkers(null,'pause',${id})">暂停本团队</button><button class="secondary" onclick="controlWorkers(null,'resume',${id})">恢复本团队</button><button class="secondary" onclick="chat(${id})">与指挥对话</button></div></div><section class="panel"><div class="panel-head"><h2>直属员工 · L3</h2><span class="muted small">${children.length} 位</span></div>${children.map(a=>`<div class="worker-row"><div class="avatar ${a.color}">${esc(a.name.slice(0,1))}</div><div class="worker-info"><h3>${esc(a.name)} · ${esc(a.role)}</h3><p>直属上级：${esc(m.name)}</p><small>${esc(a.status)}</small></div><div class="chief-actions"><button class="secondary" onclick="chooseProjectFor(${a.id})">分派任务</button><button class="secondary" onclick="controlWorkers(${a.id},'pause',${id})">暂停</button><button class="secondary" onclick="controlWorkers(${a.id},'resume',${id})">恢复</button><button class="secondary" onclick="chat(${a.id})">对话</button></div></div>`).join('')||'<div class="empty">添加三级员工后即可开始执行。</div>'}</section><section class="panel"><div class="panel-head"><h2>参与项目</h2></div>${rows(projects.filter(p=>p.tasks.some(t=>children.some(a=>a.id===t.agent))))}</section>`;sync()}
function newManager(){editDepartment()}
function createManager(form){const d=new FormData(form),name=d.get('name').trim(),dept=d.get('dept').trim();if(!name||!dept)return;const m={id:-Date.now(),name,dept,role:'性能指挥',level:2,parentId:0,status:'等待调度',model:'manager-model',endpoint:'https://api.example.com/v1'};managers.push(m);closeModal();managerPanel(m.id);toast('部门负责人已创建，请添加直属员工')}
function newAgent(pid=null,mid=null){modal('创建三级员工',pid?'项目已创建。选择部门负责人，为其招募执行员工。':'每位三级员工必须归属一位部门负责人。',`<form onsubmit="event.preventDefault();createAgent(this,${pid})"><label class="field">员工名称<input name="name" required maxlength="12" placeholder="例如：小助"></label><label class="field">员工职责<input name="role" required placeholder="例如：项目执行专员"></label><label class="field">直属负责人<select name="parentId">${managers.map(m=>`<option value="${m.id}" ${mid===m.id?'selected':''}>${esc(m.name)} · ${esc(m.dept)}</option>`).join('')}</select></label><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">稍后添加</button><button class="primary">创建员工</button></div></form>`)}
function createAgent(form,pid){const d=new FormData(form),m=managers.find(m=>m.id===Number(d.get('parentId')));if(!m)return toast('请选择直属性能指挥');const a={id:Date.now(),name:d.get('name').trim()||'新员工',role:d.get('role'),dept:m.dept,parentId:m.id,level:3,status:'等待新任务',color:'mint',model:'custom-model',endpoint:'https://api.example.com/v1'};agents.push(a);closeModal();if(pid){projects.find(p=>p.id===pid).tasks.push({name:'制定项目执行方案',status:'todo',agent:a.id,supervisorId:m.id});project(pid)}else managerPanel(m.id);toast(`员工已加入${m.name}的团队`)}
function controlWorkers(id,action,mid=null){const scope=agents.filter(a=>(mid===null||a.parentId===mid)&&(id===null||a.id===id));let n=0;for(const p of projects)for(const t of p.tasks){if(!scope.some(a=>a.id===t.agent))continue;if(action==='pause'&&t.status==='doing'){t.runToken=(t.runToken||0)+1;t.status='todo';t.phase='paused';n++}else if(action==='resume'&&!p.paused&&t.status==='todo'&&t.phase==='paused'&&t.agent){readBeforeRun(p,t);n++}}logs.unshift([`${mid===null?'总指挥经部门负责人':findAgent(mid).name}${action==='pause'?'暂停':'恢复'} ${n} 项任务（模拟）`,'刚刚']);refresh();toast(`已${action==='pause'?'暂停':'恢复'} ${n} 项任务`)}
function autoAssignAll(mid=null){const pool=agents.filter(a=>supervisor(a)&&(mid===null||a.parentId===mid));if(!pool.length)return toast('本团队暂无员工，请先添加');let n=0;for(const p of projects.filter(p=>!p.paused))for(const t of p.tasks.filter(t=>t.status==='todo'&&t.phase!=='paused')){if(mid!==null&&((t.agent&&!pool.some(a=>a.id===t.agent))||(!t.agent&&t.supervisorId!==mid)))continue;let a=pool.find(a=>a.id===t.agent);if(!a)a=[...pool].sort((x,y)=>projects.flatMap(p=>running(p)).filter(t=>t.agent===x.id).length-projects.flatMap(p=>running(p)).filter(t=>t.agent===y.id).length)[0];t.agent=a.id;t.supervisorId=a.parentId;readBeforeRun(p,t);logs.unshift([`总指挥 → ${supervisor(a).name} → ${a.name}：分派「${t.name}」（模拟）`,'刚刚']);n++}refresh();toast(n?`已分派 ${n} 项任务，员工先阅读 README`:'没有待分派的本团队任务；可从员工行添加任务')}
function assign(id,preferred=null,mid=null){const p=projects.find(p=>p.id===id);if(preferred!==null)mid=agents.find(a=>a.id===preferred)?.parentId??mid;const pool=agents.filter(a=>supervisor(a)&&(mid===null||a.parentId===mid));if(!pool.length)return toast('请先添加三级员工');modal(mid===null?'总指挥 → 性能指挥 → 员工':`${esc(findAgent(mid).name)} · 分派任务`,'任务经部门负责人分派给三级员工执行。',`<form onsubmit="event.preventDefault();dispatch(this,${id},${mid})"><label class="field">待分派任务<select name="task"><option value="new">＋ 新建任务</option>${p.tasks.map((t,i)=>t.status==='todo'&&(mid===null||t.supervisorId===mid||(!t.agent&&!t.supervisorId))?`<option value="${i}">${esc(t.name)}</option>`:'').join('')}</select></label><label class="field">新任务名称<input name="title" placeholder="选择新建任务时填写"></label><label class="field">部门负责人 → 执行员工<select name="agent">${pool.map(a=>`<option value="${a.id}" ${preferred===a.id?'selected':''}>${esc(supervisor(a).name)} → ${esc(a.name)}</option>`).join('')}</select></label><div class="notice">三级员工先阅读最新 README，再开始模拟执行。部门负责人只可分派自己的员工。</div><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="primary">确认分派</button></div></form>`)}
function dispatch(form,id,mid=null){const d=new FormData(form),p=projects.find(p=>p.id===id),a=agents.find(a=>a.id===Number(d.get('agent')));if(p?.paused)return toast('项目已暂停，请先点击项目的开始按钮');if(!p||!a||!supervisor(a)||mid!==null&&a.parentId!==mid)return toast('只能分派当前指挥的直属员工');let t;if(d.get('task')==='new'){if(!d.get('title').trim())return toast('请填写新任务名称');t={id:crypto.randomUUID(),name:d.get('title').trim(),status:'todo',agent:a.id};p.tasks.push(t)}else{t=p.tasks[+d.get('task')];if(!t||t.status!=='todo'||mid!==null&&t.supervisorId&&t.supervisorId!==mid)return toast('不能操作其他指挥的任务');t.agent=a.id}t.supervisorId=a.parentId;logs.unshift([`总指挥 → ${supervisor(a).name} → ${a.name}：分派「${t.name}」（模拟）`,'刚刚']);readBeforeRun(p,t);closeModal();project(id);toast('已通过性能指挥分派，员工正在阅读 README')}
function projectControls(p){const active=!p.paused&&running(p).length>0;const label=active?'暂停项目':'开始项目';return `<div class="project-controls"><button class="${active?'secondary':'primary'} icon-button" aria-label="${label}" title="${active?'暂停项目：该项目全员停手':'开始项目'}" onclick="${active?'pauseProject':'startProject'}(${p.id})" ${!active&&!p.tasks.some(t=>t.status==='todo')?'disabled':''}>${uiIcon(active?'pause':'play')}</button></div>`}
function pauseProject(id){const p=projects.find(p=>p.id===id);if(!p||p.paused)return;p.paused=true;let n=0;for(const t of p.tasks){t.runToken=(t.runToken||0)+1;if(t.status==='doing'){t.status='todo';t.phase='paused';n++}}logs.unshift([`「${p.name}」已暂停：${n} 项执行已停止，所有员工等待项目重新开始（模拟）`,'刚刚']);refresh();toast('项目已暂停，该项目所有员工已停手')}
function startProject(id){const p=projects.find(p=>p.id===id);if(!p)return;p.paused=false;let n=0;for(const t of p.tasks.filter(t=>t.status==='todo')){let a=agents.find(a=>a.id===t.agent&&supervisor(a));if(!a){const pool=agents.filter(a=>supervisor(a)&&(!t.supervisorId||a.parentId===t.supervisorId));a=[...pool].sort((a,b)=>projects.flatMap(p=>running(p)).filter(t=>t.agent===a.id).length-projects.flatMap(p=>running(p)).filter(t=>t.agent===b.id).length)[0]}if(!a)continue;t.agent=a.id;t.supervisorId=a.parentId;readBeforeRun(p,t);n++}logs.unshift([`「${p.name}」开始：经性能指挥启动 ${n} 项任务，员工先阅读最新 README（模拟）`,'刚刚']);refresh();toast(n?`已启动 ${n} 项任务，员工正在阅读 README`:'暂无可启动的任务；异常任务请处理后单独重试')}

function teamEvents(items,compact=false){return items.map(l=>`<div class="event"><span class="point"></span><span class="${compact?'activity-summary':''}" title="${esc(l[0])}">${esc(l[0])}</span><time>${esc(l[1])}</time></div>`).join('')||'<div class="empty">暂无团队动态</div>'}
function showTeamActivity(){modal('团队动态详情',`按最新在前展示，共 ${logs.length} 条当前保留的动态。`,`<div class="timeline activity-details">${teamEvents(logs)}</div><div class="modal-footer"><button class="secondary" onclick="closeModal()">关闭</button></div>`)}

function uiIcon(name){const paths={play:'<path d="m8 5 11 7-11 7Z" fill="currentColor" stroke="none"/>',pause:'<path d="M8 5v14M16 5v14" stroke-width="3"/>',edit:'<path d="m15 5 4 4M4 20l5-1L20 8a2.8 2.8 0 0 0-4-4L5 15Z"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 11v5M14 11v5"/>',chat:'<path d="M20 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 18 0ZM7 10h8M7 14h5"/>'};return `<svg class="ui-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.chat}</svg>`}
